{
  "apiVersion": "apps/v1",
  "kind": "Deployment",
  "metadata": {
    "name": "api",
    "namespace": "payments"
  },
  "spec": {
    "template": {
      "spec": {
        "containers": [
          {
            "name": "api",
            "image": "example/api:v1",
            "resources": {
              "requests": {
                "cpu": "300m",
                "memory": "256Mi"
              }
            }
          }
        ]
      }
    }
  }
}
